-- Nuvenzinha: avaliação no Google (atalho /avaliar leva para o formulário do Perfil da Empresa) e o portfólio do fotógrafo.
INSERT INTO faq (ordem, pergunta, palavras, resposta) VALUES
(69, 'Como avalio a Master Nuvem no Google?', 'avaliar, avaliacao, avaliacoes, estrelas, nota, google, recomendar, indicar, elogio, review, depoimento',
 'Que bom que você gostou! A sua avaliação ajuda muito outras pessoas a encontrar a gente. É só abrir [masternuvem.com.br/avaliar](/avaliar), escolher as estrelas e escrever umas palavrinhas. Leva 1 minuto.'),
(70, 'Tem página de portfólio para fotógrafo?', 'portfolio, pagina de vendas, site do fotografo, meu site, vitrine, mostrar trabalhos, divulgar, orcamento, pedir orcamento, aparecer no google, instagram',
 'Tem sim! Em [Meu estúdio → 🌟 Portfólio](/meu-portal?aba=portfolio) você monta a sua página de vendas: galerias com as suas melhores fotos, capa, cidade, WhatsApp, Instagram e um botão "Pedir orçamento" (o pedido chega no seu e-mail). Ela fica em masternuvem.com.br/f/seu-estudio, aberta para qualquer pessoa e para o Google. Coloque o link na bio do Instagram!');
